create or replace function public.card_ensures_board_access(p_card_id bigint, p_require_editor_final boolean)
returns trigger
language plpgsql
as $$
begin
  if (select auth.role()) = 'service_role' then
    return new;
  end if;

  perform 1 from public.board_members bm where bm.board_id = new.board_id and bm.user_id = (select auth.uid());
  if not found then
    raise exception 'card % is not on a board accessible to the current user', p_card_id;
  end if;

  if p_require_editor_final and not public.is_board_editor(new.board_id) then
    raise exception 'card % can only be moved to boards where the current user is an editor', p_card_id;
  end if;

  return new;
end;
$$;

create trigger cards_enforce_board_access
before insert or update on public.cards
for each row execute function public.card_ensures_board_access(new.id, coalesce((select c.column_name != old.column_name from public.cards c where c.id = new.id), false));

