create or replace function public.enforce_friendship_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendship insert requires authenticated user';
  end if;
  if new.requester_id <> auth.uid() then
    raise exception 'you can only send friend requests as yourself';
  end if;
  if new.status <> 'pending' then
    raise exception 'new friendship requests must be pending';
  end if;
  if new.requester_id = new.addressee_id then
    raise exception 'you cannot send a friend request to yourself';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null then
    raise exception 'friendship update requires authenticated user';
  end if;
  if tg_op = 'INSERT' then
    if public.friendship_request_pending(new.requester_id, new.addressee_id) then
      return new;
    else
      raise exception 'friendship request is not pending';
    end if;
  elsif tg_op = 'UPDATE' then
    if old.status <> 'pending' then
      raise exception 'only pending friendship requests can be accepted';
    end if;
    if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
      raise exception 'friendship identifiers cannot be changed';
    end if;
    if new.status <> 'accepted' then
      raise exception 'friendship request can only be accepted';
    end if;
    if public.is_friend(auth.uid(), old.requester_id) and public.is_friend(auth.uid(), old.addressee_id) then
      raise exception 'neither party can accept their own friendship request';
    end if;
    return new;
  else
    raise exception 'invalid trigger operation';
  end if;
end;
$$;

